// Extract and validate the two uploaded files from the webhook
const body = $json.body || $json;
const files = body.files || {};

// Expect: rapport (doctor report) and ordonnance (prescription)
const rapport = files.rapport || body.rapport_base64;
const ordonnance = files.ordonnance || body.ordonnance_base64;
const patient_id = body.patient_id;

if (!patient_id) {
  throw new Error('patient_id is required');
}

if (!rapport && !ordonnance) {
  throw new Error('At least one document is required: rapport (doctor report) or ordonnance (prescription)');
}

return [{
  json: {
    patient_id,
    has_rapport: !!rapport,
    has_ordonnance: !!ordonnance,
    rapport_data: rapport || null,
    ordonnance_data: ordonnance || null,
    upload_timestamp: new Date().toISOString()
  }
}];

// Parse Claude's report extraction response and validate
const raw = $json.content[0].text.replace(/```json|```/g, '').trim();
let data;
try {
  data = JSON.parse(raw);
} catch (e) {
  throw new Error('Failed to parse Claude report response as JSON: ' + e.message);
}

const patient_id = $('Validate Input & Extract Files').item.json.patient_id;

// Identify low-confidence fields
const lowConfidence = [];
const scores = data.confidence_scores || {};
for (const [field, score] of Object.entries(scores)) {
  if (typeof score === 'number' && score < 0.7) {
    lowConfidence.push(field);
  }
}

// Check medication confidence
if (data.medicaments) {
  data.medicaments.forEach((med, idx) => {
    if (med.confidence && med.confidence < 0.7) {
      lowConfidence.push(`medicaments[${idx}].${med.nom}`);
    }
  });
}

return [{
  json: {
    patient_id,
    document_type: 'DOCTOR_REPORT',
    extraction: data,
    low_confidence_fields: lowConfidence,
    confidence_scores: scores,
    is_valid: true
  }
}];

// Parse Claude's prescription extraction response and validate
const raw = $json.content[0].text.replace(/```json|```/g, '').trim();
let data;
try {
  data = JSON.parse(raw);
} catch (e) {
  throw new Error('Failed to parse Claude prescription response as JSON: ' + e.message);
}

const patient_id = $('Validate Input & Extract Files').item.json.patient_id;

// Sanity checks
const warnings = [];
if (!data.medicaments || data.medicaments.length === 0) {
  warnings.push('No medications extracted from prescription');
}

// Dose sanity: check frequencies and times
if (data.medicaments) {
  data.medicaments.forEach((med, idx) => {
    if (!med.posologie) {
      warnings.push(`Medication ${med.nom}: missing posologie`);
    }
    if (!med.heures_prises || med.heures_prises.length === 0) {
      // Auto-assign based on frequency
      const freq = (med.frequence || '').toLowerCase();
      if (freq.includes('1') || freq.includes('une')) {
        med.heures_prises = ['08:00'];
      } else if (freq.includes('2') || freq.includes('deux')) {
        med.heures_prises = ['08:00', '20:00'];
      } else if (freq.includes('3') || freq.includes('trois')) {
        med.heures_prises = ['08:00', '13:00', '20:00'];
      } else {
        med.heures_prises = ['08:00'];
      }
      warnings.push(`Medication ${med.nom}: times auto-assigned to ${med.heures_prises.join(', ')}`);
    }
  });
}

const lowConfidence = [];
const scores = data.confidence_scores || {};
for (const [field, score] of Object.entries(scores)) {
  if (typeof score === 'number' && score < 0.7) {
    lowConfidence.push(field);
  }
}

data.medicaments?.forEach((med, idx) => {
  if (med.confidence && med.confidence < 0.7) {
    lowConfidence.push(`medicaments[${idx}].${med.nom}`);
  }
});

return [{
  json: {
    patient_id,
    document_type: 'PRESCRIPTION',
    extraction: data,
    low_confidence_fields: lowConfidence,
    confidence_scores: scores,
    warnings,
    is_valid: data.medicaments && data.medicaments.length > 0
  }
}];

// Merge results from both draft saves (report and/or prescription)
const items = $input.all();
const results = {
  drafts: [],
  low_confidence_fields: [],
  warnings: [],
  patient_id: $('Validate Input & Extract Files').item.json.patient_id,
  requires_review: false,
  avertissement: 'Ces données extraites sont un BROUILLON. Veuillez les vérifier avant de les appliquer. Cette application ne remplace pas l\'avis de votre médecin.'
};

for (const item of items) {
  const d = item.json;
  if (d.document_source_id) {
    results.drafts.push({
      document_source_id: d.document_source_id,
      document_type: d.document_type,
      status: d.status,
      version: d.version
    });
  }
  if (d.low_confidence_fields && d.low_confidence_fields.length > 0) {
    results.low_confidence_fields.push(...d.low_confidence_fields);
    results.requires_review = true;
  }
  if (d.warnings) {
    results.warnings.push(...(Array.isArray(d.warnings) ? d.warnings : []));
  }
}

return [{ json: results }];
